css='body{font:16px/1.55 Inter,system-ui;margin:0;background:#faf9f4;color:#20251c}main{max-width:1500px;margin:auto;padding:35px}h1{font-size:36px}section{margin:45px 0;padding-top:20px;border-top:1px solid #aaa}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px}.pair figure{margin:0;min-width:0}.pair img{width:100%;border:1px solid #aaa;vertical-align:top}a{color:#36533d}dt{font-weight:700;margin-top:10px}dd{margin-left:0}figcaption{min-height:80px;font-size:14px}@media(max-width:700px){.pair{grid-template-columns:1fr}}'
body='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pantry research comparisons</title><style>'+css+'</style><main><a href="../index.html">Back to storybook</a><h1>Pantry · reference comparisons</h1><p>Research evidence is separate from original design. No Shopify imagery, copy or logos are used in Pantry storefront source. Saved references retain original appearance; remote pages were never restyled.</p>'
