for s,label in [('01-home-top','Compact introduction → category shortcuts → shelf rows'),('03-collection','Named shelf groups → contained pack + price/net-quantity rows'),('04-product-main','Package → ingredients/allergen status → pack/quantity purchase panel')]:neutral+=f'<h2>{label}</h2><iframe title="Neutral {s}" src="../source/{s}.html?neutral=1"></iframe>'
